begin;
create extension if not exists pgtap with schema extensions;
insert into auth.users(id,email,email_confirmed_at) values('da400000-0000-0000-0000-000000000001','a2-manage@example.test',now());
insert into public.admin_allowlist(email,level) values('a2-manage@example.test','owner');
insert into public.events(id,slug,name) values('ea400000-0000-0000-0000-000000000001','a2-management','A2 management'),('ea400000-0000-0000-0000-000000000002','a2-management-other','Other');
insert into public.event_competition_settings(event_id,enabled,project_submissions_open_at,project_submissions_close_at,judging_close_at,general_reviews_per_project)
select id,true,now()-interval '2 days',now()-interval '1 day',now()+interval '1 day',1 from public.events where slug like 'a2-management%';
insert into public.projects(id,event_id,owner_user_id,name,status,submitted_at) values('aa400000-0000-0000-0000-000000000001','ea400000-0000-0000-0000-000000000001','da400000-0000-0000-0000-000000000001','Project','submitted',now());
insert into public.event_judges(id,event_id,email,capacity) select ('ba400000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'ea400000-0000-0000-0000-000000000001','a2-manual-'||n||'@example.test',1 from generate_series(1,4)n;
update public.event_competition_settings set judging_started_at=now(),judging_close_at=now()-interval '1 hour' where event_id in ('ea400000-0000-0000-0000-000000000001','ea400000-0000-0000-0000-000000000002');
select set_config('request.jwt.claims','{"sub":"da400000-0000-0000-0000-000000000001","email":"a2-manage@example.test","amr":[{"method":"oauth"}]}',true);
create function pg_temp.add(n integer) returns uuid language sql as $$select public.admin_add_assignment('ea400000-0000-0000-0000-000000000001','aa400000-0000-0000-0000-000000000001',('ba400000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid)$$;
create function pg_temp.cancel() returns void language sql as $$select public.admin_cancel_assignment('ea400000-0000-0000-0000-000000000001',current_setting('test.source')::uuid)$$;
create function pg_temp.reassign(n integer) returns uuid language sql as $$select public.admin_reassign_assignment('ea400000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,('ba400000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid)$$;
insert into public.judging_criteria(id,event_id,position,name) values('fa400000-0000-0000-0000-000000000001','ea400000-0000-0000-0000-000000000001',1,'Criterion A');
select plan(22);
set local role authenticated;
select lives_ok($$select set_config('test.source',pg_temp.add(1)::text,true)$$,'manual addition allowed after expiry without reopening judging');
select throws_ok($$select pg_temp.add(2)$$,'P0001','This project context has no missing assignments','cannot overfill context');
select throws_ok($$select pg_temp.reassign(1)$$,'P0001','Judge is no longer eligible for this assignment','cannot recycle source pair');
reset role;
select ok(not (select cancelled from public.judging_assignments where id=current_setting('test.source')::uuid),'failed replacement atomically restores source');
set local role authenticated;
select lives_ok($$select set_config('test.replacement',pg_temp.reassign(2)::text,true)$$,'untouched assignment replaced');
select throws_ok($$select pg_temp.reassign(3)$$,'P0001','Assignment is already cancelled; refresh before continuing','stale repeat cannot add another replacement');
select lives_ok($$select pg_temp.cancel()$$,'repeat cancellation safe');
select throws_ok($$select public.admin_cancel_assignment('ea400000-0000-0000-0000-000000000002',current_setting('test.replacement')::uuid)$$,'PT404','Assignment not found for this event','foreign source rejected');
reset role;
select ok((select cancelled from public.judging_assignments where id=current_setting('test.source')::uuid),'old row retained cancelled');
select is((select count(*) from public.judging_assignments where not cancelled and project_id='aa400000-0000-0000-0000-000000000001'),1::bigint,'replacement preserves coverage');
select set_config('test.source',current_setting('test.replacement'),true);
update public.judging_assignments set notes='saved note' where id=current_setting('test.source')::uuid;
set local role authenticated;
select throws_ok($$select pg_temp.cancel()$$,'P0001','Only untouched assignments can be cancelled or reassigned','notes prevent cancellation');
select throws_ok($$select pg_temp.reassign(3)$$,'P0001','Only untouched assignments can be cancelled or reassigned','notes prevent reassignment');
reset role;
update public.judging_assignments set notes='' where id=current_setting('test.source')::uuid;
insert into public.judging_scores values(current_setting('test.source')::uuid,'fa400000-0000-0000-0000-000000000001','ea400000-0000-0000-0000-000000000001',1);
set local role authenticated;
select throws_ok($$select pg_temp.reassign(3)$$,'P0001','Only untouched assignments can be cancelled or reassigned','one draft score prevents moving work');
reset role;
update public.judging_assignments set submitted_at=now() where id=current_setting('test.source')::uuid;
set local role authenticated;
select throws_ok($$select pg_temp.cancel()$$,'P0001','Only untouched assignments can be cancelled or reassigned','submitted work protected');
reset role;
-- Privileged fixture resets only, not a client review-reopening operation.
delete from public.judging_scores where assignment_id=current_setting('test.source')::uuid;
update public.judging_assignments set submitted_at=null where id=current_setting('test.source')::uuid;
set local role authenticated;
select lives_ok($$select pg_temp.cancel()$$,'untouched cancellation allowed');
select throws_ok($$select pg_temp.add(1)$$,'P0001','Judge is no longer eligible for this assignment','cancelled original pair blocked manually');
select throws_ok($$select pg_temp.add(2)$$,'P0001','Judge is no longer eligible for this assignment','cancelled replacement pair blocked manually');
select lives_ok($$select pg_temp.add(3)$$,'another eligible judge can fill cancelled coverage');
reset role;
select is((select count(*) from public.judging_assignments where cancelled),2::bigint,'history retained');
select is((select count(*) from public.judging_assignments where not cancelled),1::bigint,'only one active replacement');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select pg_temp.add(4)$$,'42501','Not authorized','nonorganizer denied');
reset role;
set local role anon;
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'anonymous management denied');
select * from finish(true);
rollback;
